#include <iostream>
#include <vector>
#include <string>
#include <cctype>
using namespace std;

vector<string> scan_tokens(const string& source) {
    vector<string> tokens;
    size_t i = 0;
    while (i < source.size()) {
        unsigned char character = static_cast<unsigned char>(source[i]);
        if (isspace(character)) { ++i; continue; }
        if (isdigit(character)) {
            size_t start = i;
            while (i < source.size() && isdigit(static_cast<unsigned char>(source[i]))) ++i;
            tokens.push_back(source.substr(start, i - start));
        } else {
            tokens.push_back(source.substr(i, 1));
            ++i;
        }
    }
    return tokens;
}

int main() {
    string source; getline(cin, source);
    auto tokens = scan_tokens(source);
    cout << tokens.size() << "\n";
    for (size_t i = 0; i < tokens.size(); ++i) { if (i) cout << " "; cout << tokens[i]; }
    cout << "\n";
}

