pair<int, int> cache_counts(int capacity, const vector<int>& requests) {
    return {0, static_cast<int>(requests.size())};
}

int main() {
    int capacity, n; cin >> capacity >> n;
    vector<int> requests(n); for (int& key : requests) cin >> key;
    auto [hits, misses] = cache_counts(capacity, requests);
    cout << hits << " " << misses << "\n";
}

challenges.reference_solution:
#include <iostream>
#include <vector>
#include <utility>
#include <unordered_map>
#include <list>
using namespace std;

pair<int, int> cache_counts(int capacity, const vector<int>& requests) {
    list<int> recency;
    unordered_map<int, list<int>::iterator> position;
    int hits = 0, misses = 0;
    for (int key : requests) {
        auto found = position.find(key);
        if (found != position.end()) {
            ++hits;
            recency.splice(recency.begin(), recency, found->second);
        } else {
            ++misses;
            recency.push_front(key);
            position[key] = recency.begin();
            if (static_cast<int>(recency.size()) > capacity) {
                position.erase(recency.back());
                recency.pop_back();
            }
        }
    }
    return {hits, misses};
}

int main() {
    int capacity, n; cin >> capacity >> n;
    vector<int> requests(n); for (int& key : requests) cin >> key;
    auto [hits, misses] = cache_counts(capacity, requests);
    cout << hits << " " << misses << "\n";
}

