challenges.reference_solution:
#include <iostream>
#include <vector>
#include <string>
#include <utility>
#include <queue>
using namespace std;

int rescue_distance(const vector<string>& grid) {
    int rows = static_cast<int>(grid.size()), columns = static_cast<int>(grid[0].size());
    vector<vector<int>> distance(rows, vector<int>(columns, -1));
    queue<pair<int, int>> frontier;
    for (int r = 0; r < rows; ++r) for (int c = 0; c < columns; ++c) {
        if (grid[r][c] == 'S') { distance[r][c] = 0; frontier.push({r, c}); }
    }
    const int dr[] = {-1, 1, 0, 0}, dc[] = {0, 0, -1, 1};
    while (!frontier.empty()) {
        auto [r, c] = frontier.front(); frontier.pop();
        if (grid[r][c] == 'E') return distance[r][c];
        for (int direction = 0; direction < 4; ++direction) {
            int nr = r + dr[direction], nc = c + dc[direction];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= columns) continue;
            if (grid[nr][nc] == '#' || distance[nr][nc] != -1) continue;
            distance[nr][nc] = distance[r][c] + 1;
            frontier.push({nr, nc});
        }
    }
    return -1;
}

int main() {
    int rows, columns; cin >> rows >> columns;
    vector<string> grid(rows); for (string& row : grid) cin >> row;
    cout << rescue_distance(grid) << "\n";
}

