challenges.reference_solution:
#include <iostream>
#include <vector>
#include <utility>
#include <queue>
#include <functional>
using namespace std;

vector<int> build_order(int n, const vector<pair<int, int>>& edges) {
    vector<vector<int>> consumers(n);
    vector<int> indegree(n, 0);
    for (auto [u, v] : edges) { consumers[u].push_back(v); ++indegree[v]; }
    priority_queue<int, vector<int>, greater<int>> ready;
    for (int target = 0; target < n; ++target) if (indegree[target] == 0) ready.push(target);
    vector<int> order;
    while (!ready.empty()) {
        int target = ready.top(); ready.pop(); order.push_back(target);
        for (int consumer : consumers[target]) if (--indegree[consumer] == 0) ready.push(consumer);
    }
    if (static_cast<int>(order.size()) != n) return {};
    return order;
}

int main() {
    int n, m; cin >> n >> m;
    vector<pair<int, int>> edges(m); for (auto& [u, v] : edges) cin >> u >> v;
    auto order = build_order(n, edges);
    if (order.empty()) { cout << "CYCLE\n"; return 0; }
    for (size_t i = 0; i < order.size(); ++i) { if (i) cout << " "; cout << order[i]; }
    cout << "\n";
}

