#include <iostream>
#include <vector>
#include <string>
#include <utility>
using namespace std;

long long execute_bytecode(const vector<pair<string, long long>>& program) {
    vector<long long> stack;
    for (const auto& [operation, argument] : program) {
        if (operation == "PUSH") { stack.push_back(argument); continue; }
        long long rhs = stack.back(); stack.pop_back();
        long long lhs = stack.back(); stack.pop_back();
        if (operation == "ADD") stack.push_back(lhs + rhs);
        else if (operation == "SUB") stack.push_back(lhs - rhs);
        else stack.push_back(lhs * rhs);
    }
    return stack.back();
}

int main() {
    int n; cin >> n;
    vector<pair<string, long long>> program;
    for (int i = 0; i < n; ++i) {
        string operation; long long argument = 0; cin >> operation;
        if (operation == "PUSH") cin >> argument;
        program.push_back({operation, argument});
    }
    cout << execute_bytecode(program) << "\n";
}

