long long shortest_delay(int n, const vector<vector<long long>>& edges, int source, int target) {
    vector<vector<pair<int, long long>>> graph(n);
    for (const auto& edge : edges) graph[edge[0]].push_back({static_cast<int>(edge[1]), edge[2]});
    const long long infinity = numeric_limits<long long>::max() / 4;
    vector<long long> distance(n, infinity);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> queue;
    distance[source] = 0; queue.push({0, source});
    while (!queue.empty()) {
        auto [cost, node] = queue.top(); queue.pop();
        if (cost != distance[node]) continue;
        if (node == target) return cost;
        for (auto [next, weight] : graph[node]) {
            if (cost + weight < distance[next]) {
                distance[next] = cost + weight;
                queue.push({distance[next], next});
            }
        }
    }
    return -1;
}

int main() {
    int n, m, source, target; cin >> n >> m >> source >> target;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (auto& edge : edges) cin >> edge[0] >> edge[1] >> edge[2];
    cout << shortest_delay(n, edges, source, target) << "\n";
}

