#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>
using namespace std;

long long best_quality(int budget, const vector<pair<int, int>>& effects) {
    vector<long long> dp(budget + 1, 0);
    for (auto [cost, quality] : effects) {
        for (int b = budget; b >= cost; --b) dp[b] = max(dp[b], dp[b - cost] + quality);
    }
    return dp[budget];
}

int main() {
    int n, budget; cin >> n >> budget;
    vector<pair<int, int>> effects(n); for (auto& [cost, quality] : effects) cin >> cost >> quality;
    cout << best_quality(budget, effects) << "\n";
}
